script.setup:
// dlaf by Michael Fogleman (MIT, https://github.com/fogleman/dlaf): diffusion-limited aggregation.
// dlaf is C++ (one file, dlaf.cpp at commit fc684bd), so this is a port of its Model class to JS:
// same parameters (ParticleSpacing, AttractionDistance, MinMoveDistance, Stubbornness, Stickiness), same
// hooks (RandomStartingPosition, ShouldReset, ShouldJoin, PlaceParticle, MotionVector) and the same walk:
// a particle jumps by max(MinMoveDistance, distance to the nearest particle - AttractionDistance), which is
// what makes it fast. Boost's R-tree is replaced by a uniform grid; when nothing is found within the
// searched rings the walk uses a lower bound of the distance instead (never overshoots the cluster).
// Seed variants use dlaf's hooks the way its README suggests: the ring of seeds is the commented-out block
// in dlaf.cpp's main() (particles released inside it grow the ring inward), and the coral mode seeds a
// ground line with particles released above the tallest branch. 3D is dlaf's D = 3.
const gl = ctx.gl, s = ctx.state;
const MAXN = 60000;
const CELL = 4;

function makeModel(dim, mode, u) {
  const G = dim === 2 ? 512 : 96; // grid cells per axis
  const cells = dim === 2 ? G * G : G * G * G;
  const m = {
    dim, mode, G, half: G / 2,
    head: new Int32Array(cells).fill(-1), next: new Int32Array(MAXN),
    pts: new Float32Array(MAXN * 3), parent: new Int32Array(MAXN), joins: new Int32Array(MAXN),
    n: 0, uploaded: 0, maxLen: 0, boundingRadius: 0, walker: null, done: false, innerR: Infinity, topY: 0, width: 0,
    ring: 0, spacing: u.u_spacing, attraction: u.u_attraction, minMove: u.u_minmove,
    stubbornness: Math.round(u.u_stubborn), stickiness: u.u_sticky,
  };
  return m;
}
function cellOf(m, x, y, z) {
  const cx = Math.floor(x / CELL) + m.half, cy = Math.floor(y / CELL) + m.half;
  if (cx < 0 || cy < 0 || cx >= m.G || cy >= m.G) return -1;
  if (m.dim === 2) return cy * m.G + cx;
  const cz = Math.floor(z / CELL) + m.half;
  if (cz < 0 || cz >= m.G) return -1;
  return (cz * m.G + cy) * m.G + cx;
}
// Model::Add
function add(m, x, y, z, parent) {
  if (m.n >= MAXN) { m.done = true; return; }
  const i = m.n++;
  m.pts[i * 3] = x; m.pts[i * 3 + 1] = y; m.pts[i * 3 + 2] = z;
  m.parent[i] = parent; m.joins[i] = 0;
  const c = cellOf(m, x, y, z);
  if (c >= 0) { m.next[i] = m.head[c]; m.head[c] = i; }
  const len = Math.hypot(x, y, z);
  m.maxLen = Math.max(m.maxLen, len);
  m.boundingRadius = Math.max(m.boundingRadius, len + m.attraction);
  if (parent >= 0) { m.innerR = Math.min(m.innerR, len); m.topY = Math.max(m.topY, y); }
}
// Model::Nearest, plus a distance. Returns index (or -1 with s.lb = lower bound of the distance).
let nearestD = 0;
function nearest(m, x, y, z) {
  const K = m.dim === 2 ? 6 : 3;
  const cx = Math.floor(x / CELL) + m.half, cy = Math.floor(y / CELL) + m.half, cz = m.dim === 3 ? Math.floor(z / CELL) + m.half : 0;
  let best = Infinity, bi = -1;
  const G = m.G, P = m.pts, head = m.head, next = m.next;
  for (let k = 0; k <= K; k++) {
    const z0 = m.dim === 3 ? -k : 0, z1 = m.dim === 3 ? k : 0;
    for (let dz = z0; dz <= z1; dz++) {
      const zz = cz + dz;
      if (zz < 0 || zz >= G) continue;
      for (let dy = -k; dy <= k; dy++) {
        const yy = cy + dy;
        if (yy < 0 || yy >= G) continue;
        const edgeYZ = Math.abs(dy) === k || Math.abs(dz) === k;
        for (let dx = -k; dx <= k; dx += (edgeYZ ? 1 : 2 * k || 1)) {
          const xx = cx + dx;
          if (xx < 0 || xx >= G) continue;
          let i = head[m.dim === 2 ? yy * G + xx : (zz * G + yy) * G + xx];
          while (i >= 0) {
            const ex = P[i * 3] - x, ey = P[i * 3 + 1] - y, ez = P[i * 3 + 2] - z;
            const d2 = ex * ex + ey * ey + ez * ez;
            if (d2 < best) { best = d2; bi = i; }
            i = next[i];
          }
        }
      }
    }
    // anything in ring k+1 or beyond is at least k*CELL away
    if (bi >= 0 && Math.sqrt(best) <= k * CELL) break;
  }
  if (bi >= 0) { nearestD = Math.sqrt(best); return bi; }
  // lower bound of the distance: K rings were empty, and every particle lies inside maxLen (below topY for coral)
  nearestD = Math.max(K * CELL, m.mode === 3 ? y - m.topY : m.mode === 1 ? Math.min(m.innerR, m.ring) - Math.hypot(x, y) : Math.hypot(x, y, z) - m.maxLen);
  return -1;
}
// RandomInUnitSphere
const unit = [0, 0, 0];
function randomInUnitSphere(dim) {
  for (;;) {
    const x = Math.random() * 2 - 1, y = Math.random() * 2 - 1, z = dim === 2 ? 0 : Math.random() * 2 - 1;
    const l2 = x * x + y * y + z * z;
    if (l2 < 1 && l2 > 1e-9) { unit[0] = x; unit[1] = y; unit[2] = z; return unit; }
  }
}
function normalize(v) { const l = Math.hypot(v[0], v[1], v[2]); v[0] /= l; v[1] /= l; v[2] /= l; return v; }
// RandomStartingPosition: on the bounding sphere (dlaf's default); ring: anywhere inside the ring;
// coral: just above the tallest branch
function startPos(m, p) {
  if (m.mode === 3) { p[0] = (Math.random() - 0.5) * m.width; p[1] = m.topY + m.attraction + 6; p[2] = 0; return; }
  const v = normalize(randomInUnitSphere(m.dim));
  const r = m.mode === 1 ? m.ring * 0.85 * Math.sqrt(Math.random()) : m.boundingRadius;
  p[0] = v[0] * r; p[1] = v[1] * r; p[2] = v[2] * r;
}
// ShouldReset
function shouldReset(m, p) {
  if (m.mode === 3) return p[1] > m.topY + 60 || Math.abs(p[0]) > m.width * 0.5 + 4 || p[1] < -2;
  const l = Math.hypot(p[0], p[1], p[2]);
  return m.mode === 1 ? l > m.ring * 1.05 : l > m.boundingRadius * 2;
}
// ShouldJoin
function shouldJoin(m, parent) {
  m.joins[parent]++;
  if (m.joins[parent] < m.stubbornness) return false;
  return Math.random() <= m.stickiness;
}
// Lerp(a, b, d) = a + normalize(b - a) * d, written into p
function lerpFrom(m, i, p, d) {
  const ax = m.pts[i * 3], ay = m.pts[i * 3 + 1], az = m.pts[i * 3 + 2];
  let dx = p[0] - ax, dy = p[1] - ay, dz = p[2] - az, l = Math.hypot(dx, dy, dz);
  if (l < 1e-9) { const v = normalize(randomInUnitSphere(m.dim)); dx = v[0]; dy = v[1]; dz = v[2]; l = 1; }
  p[0] = ax + dx / l * d; p[1] = ay + dy / l * d; p[2] = az + dz / l * d;
}
// One step of Model::AddParticle's loop; returns true when the particle joined.
function walkStep(m) {
  if (!m.walker) { m.walker = [0, 0, 0]; startPos(m, m.walker); }
  const p = m.walker;
  const parent = nearest(m, p[0], p[1], p[2]);
  const d = nearestD;
  if (parent >= 0 && d < m.attraction) {
    if (!shouldJoin(m, parent)) { lerpFrom(m, parent, p, m.attraction + m.minMove); return false; }
    lerpFrom(m, parent, p, m.spacing); // PlaceParticle
    add(m, p[0], p[1], p[2], parent);
    m.walker = null;
    return true;
  }
  const step = Math.max(m.minMove, d - m.attraction);
  const v = normalize(randomInUnitSphere(m.dim)); // MotionVector
  p[0] += v[0] * step; p[1] += v[1] * step; p[2] += v[2] * step;
  if (shouldReset(m, p)) startPos(m, p);
  return false;
}

// ---- seeding ------------------------------------------------------------------------------------------
const MODES = ["Point", "Ring", "3D", "Coral"];
s.newModel = (mode) => {
  const u = ctx.uniforms, [w, h] = ctx.resolution;
  const m = makeModel(mode === 2 ? 3 : 2, mode, u);
  if (mode === 3) {
    // coral: a ground line of seeds as wide as the canvas is (at seeding time), grown upward
    const aspect = Math.min(2, Math.max(0.55, w / h));
    m.width = 300 * Math.min(1.2, aspect);
    m.height = Math.min(m.width / aspect, 330) * 0.92;
    for (let x = -m.width / 2; x <= m.width / 2; x += m.spacing) add(m, x, 0, 0, -1);
  } else if (mode === 1) {
    // the ring of seeds from dlaf.cpp's main() (n = 3600, r = 1000 there), scaled to a 150-unit ring
    m.ring = 150;
    const n = Math.round(2 * Math.PI * m.ring / m.spacing);
    for (let i = 0; i < n; i++) { const a = i / n * Math.PI * 2; add(m, Math.cos(a) * m.ring, Math.sin(a) * m.ring, 0, -1); }
    m.uploadFrom = 0;
  } else {
    add(m, 0, 0, 0, -1); // model.Add(Vector())
  }
  return m;
};
s.walk = (m, budgetMs, maxJoins) => {
  const t0 = performance.now();
  let joined = 0, steps = 0;
  while (!m.done && joined < maxJoins) {
    if (walkStep(m)) joined++;
    if ((++steps & 255) === 0 && performance.now() - t0 > budgetMs) break;
  }
  return joined;
};
s.add = add;
s.MODES = MODES;
s.MAXN = MAXN;

// ---- GL -----------------------------------------------------------------------------------------------
s.vbo = gl.createBuffer();
gl.bindBuffer(gl.ARRAY_BUFFER, s.vbo);
gl.bufferData(gl.ARRAY_BUFFER, MAXN * 12, gl.DYNAMIC_DRAW);
s.vao = gl.createVertexArray();
gl.bindVertexArray(s.vao);
gl.enableVertexAttribArray(0);
gl.vertexAttribPointer(0, 3, gl.FLOAT, false, 0, 0);
gl.bindVertexArray(null);

const ptVS = `#version 300 es
precision highp float;
layout(location=0) in vec3 a_p;
uniform mat4 u_mvp;
uniform float u_is3d, u_count, u_size, u_halo, u_scale2d, u_newest;
uniform vec2 u_res;
uniform vec2 u_center;
out float v_t; out float v_new; out float v_fog;
void main() {
  float id = float(gl_VertexID);
  v_t = id / max(u_count - 1.0, 1.0);
  v_new = exp(-(u_count - id) / u_newest);
  float px;
  if (u_is3d > 0.5) {
    vec4 c = u_mvp * vec4(a_p, 1.0);
    gl_Position = c;
    px = u_size / c.w;
    v_fog = clamp(1.6 - c.w * 0.32, 0.25, 1.0);
  } else {
    vec2 q = (a_p.xy - u_center) * u_scale2d / (0.5 * u_res);
    gl_Position = vec4(q, 0.0, 1.0);
    px = u_size;
    v_fog = 1.0;
  }
  gl_PointSize = clamp(px * u_halo * (1.0 + 0.8 * v_new), 1.0, u_halo > 1.5 ? 36.0 : 14.0);
}`;
const ptFS = `#version 300 es
precision highp float;
in float v_t; in float v_new; in float v_fog;
out vec4 outColor;
uniform float u_halo, u_gain, u_palette;
vec3 pal(float t) {
  // old (deep) -> young (hot); three palettes
  vec3 a, b, c, d;
  if (u_palette < 0.5) { a = vec3(0.10, 0.02, 0.22); b = vec3(0.65, 0.10, 0.55); c = vec3(1.0, 0.45, 0.15); d = vec3(1.0, 0.92, 0.65); }
  else if (u_palette < 1.5) { a = vec3(0.02, 0.08, 0.25); b = vec3(0.05, 0.45, 0.75); c = vec3(0.30, 0.95, 0.90); d = vec3(0.92, 1.0, 0.95); }
  else if (u_palette < 2.5) { a = vec3(0.12, 0.04, 0.30); b = vec3(0.25, 0.30, 0.95); c = vec3(0.55, 0.85, 1.0); d = vec3(1.0, 0.95, 1.0); }
  else { a = vec3(0.02, 0.12, 0.16); b = vec3(0.10, 0.45, 0.45); c = vec3(1.0, 0.42, 0.38); d = vec3(1.0, 0.88, 0.70); }
  t = clamp(t, 0.0, 1.0);
  return t < 0.4 ? mix(a, b, t / 0.4) : t < 0.8 ? mix(b, c, (t - 0.4) / 0.4) : mix(c, d, (t - 0.8) / 0.2);
}
void main() {
  vec2 q = gl_PointCoord * 2.0 - 1.0;
  float r2 = dot(q, q);
  if (r2 > 1.0) discard;
  float k = u_halo > 1.5 ? exp(-r2 * 5.0) * 0.07 : exp(-r2 * 3.0);
  vec3 col = pal(pow(v_t, 0.8)) * (0.55 + 0.45 * v_t) + vec3(1.0, 0.95, 0.85) * v_new * 0.9;
  outColor = vec4(col * k * u_gain * v_fog, 1.0);
}`;
const outFS = `#version 300 es
precision highp float;
in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_hdr;
uniform vec2 u_resolution;
uniform float u_exposure, u_fade, u_palette;
float hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }
void main() {
  vec3 h = texture(u_hdr, v_uv).rgb;
  // a cheap wide glow from a blurred mip
  vec2 px = 1.0 / u_resolution;
  vec3 g = vec3(0.0);
  for (int i = 0; i < 8; i++) { // jittered taps of two blurred mips, so the glow has no blocky texels
    float a = float(i) * 2.39996;
    vec2 o = vec2(cos(a), sin(a)) * sqrt(float(i) + 0.5);
    g += textureLod(u_hdr, v_uv + o * px * 12.0, 3.0).rgb * 0.08 + textureLod(u_hdr, v_uv + o * px * 40.0, 5.0).rgb * 0.1;
  }
  vec3 c = 1.0 - exp(-(h + g) * u_exposure);
  vec2 q = v_uv - 0.5; q.x *= u_resolution.x / u_resolution.y;
  vec3 bg = u_palette < 0.5 ? vec3(0.035, 0.015, 0.05) : u_palette < 1.5 ? vec3(0.01, 0.03, 0.05) : u_palette < 2.5 ? vec3(0.02, 0.02, 0.06)
    : mix(vec3(0.0, 0.025, 0.04), vec3(0.01, 0.07, 0.09), v_uv.y);
  bg *= 1.2 - 0.9 * dot(q, q);
  c = (bg + c) * u_fade + (hash(v_uv * u_resolution) - 0.5) * 0.012;
  outColor = vec4(c, 1.0);
}`;
s.ptProg = ctx.utils.createProgram(ptVS, ptFS);
s.outProg = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, outFS);
s.makeTarget = (w, h) => {
  if (s.tex) { gl.deleteTexture(s.tex); gl.deleteFramebuffer(s.fbo); }
  s.tex = gl.createTexture();
  gl.bindTexture(gl.TEXTURE_2D, s.tex);
  const levels = Math.floor(Math.log2(Math.max(w, h))) + 1;
  gl.texStorage2D(gl.TEXTURE_2D, levels, gl.RGBA16F, w, h);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  s.fbo = gl.createFramebuffer();
  gl.bindFramebuffer(gl.FRAMEBUFFER, s.fbo);
  gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, s.tex, 0);
  gl.bindFramebuffer(gl.FRAMEBUFFER, null);
  s.tw = w; s.th = h;
};
if (!gl.getExtension("EXT_color_buffer_float")) throw new Error("dlaf: needs EXT_color_buffer_float for the HDR glow buffer");
s.camera = ctx.utils.createOrbitCamera({ distance: 3.2, theta: 0.6, phi: 1.2, fov: 40, autoRotate: 0.25, minDistance: 1.2, maxDistance: 8 });
s.cycleIndex = 0;
s.start = (mode) => {
  s.model = s.newModel(mode);
  s.mode = mode;
  s.phase = "grow"; s.phaseT = 0; s.acc = 0;
  s.view = mode === 1 ? 165 : 14;
};
s.start(0);

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution;
const dt = Math.min(ctx.dt, 0.1);
s.phaseT += dt;
const chosen = Math.round(u.u_mode);
const CYCLE = [0, 3, 1, 2]; // point, coral, ring, 3D
const nextMode = () => (chosen === 4 ? CYCLE[(CYCLE.indexOf(s.mode) + 1) % 4] : chosen);
if (u.u_restart) s.start(nextMode());
else if (chosen !== 4 && chosen !== s.mode) s.start(chosen);
if (!s.tex || ctx.resized || s.tw !== w || s.th !== h) s.makeTarget(w, h);

const m = s.model;
// dlaf's Model parameters, live
m.spacing = u.u_spacing; m.attraction = u.u_attraction; m.minMove = u.u_minmove;
m.stubbornness = Math.round(u.u_stubborn); m.stickiness = u.u_sticky;

// 2D view: fit the cluster (a fixed simulation space) inside the shorter side, zooming out as it grows
const target = m.mode === 1 ? m.ring * 1.08 : m.mode === 2 ? Math.max(12, m.maxLen * 1.05 + 2) : Math.max(14, m.maxLen * 1.12 + 3);
s.view += (target - s.view) * Math.min(1, dt * 4);
let scale2d = Math.min(w, h) * 0.5 / s.view, center = [0, 0];
if (m.mode === 3) { scale2d = Math.min(w / (m.width * 1.06), h / (m.height * 1.1)); center = [0, m.height * 0.5]; }

// press to drop a new seed particle there (2D); in 3D the press orbits the camera
if (m.mode !== 2 && ctx.mouseDown && !s.wasDown && s.phase === "grow") {
  const x = (ctx.mouse[0] * w - w / 2) / scale2d + center[0], y = ((1 - ctx.mouse[1]) * h - h / 2) / scale2d + center[1];
  s.add(m, x, y, 0, -1);
}
s.wasDown = ctx.mouseDown;
if (m.mode === 2) s.camera.update(ctx.mouse, ctx.mousePrev, ctx.mouseDown, ctx.keys, ctx.dt);

if (s.phase === "grow") {
  // u_rate particles a second, slower while the cluster is tiny so its first branches can be seen forming
  s.acc = Math.min((s.acc || 0) + dt * u.u_rate * Math.min(1, 0.1 + m.n / 1500), 4000);
  s.acc -= s.walk(m, 8, Math.floor(s.acc));
    const full = m.n >= Math.min(u.u_max, s.MAXN) || m.done ||
    (m.mode === 0 && m.maxLen > 420) || (m.mode === 2 && m.maxLen > 85) || (m.mode === 1 && m.innerR < m.ring * 0.06) || (m.mode === 3 && m.topY > m.height);
  if (full) { s.phase = "rest"; s.phaseT = 0; }
} else if (s.phase === "rest" && s.phaseT > 3 && u.u_auto) { s.phase = "fade"; s.phaseT = 0; }
else if (s.phase === "fade" && s.phaseT > 1) s.start(nextMode());

if (m.uploaded > m.n) m.uploaded = 0;
if (m.uploaded < m.n) {
  gl.bindBuffer(gl.ARRAY_BUFFER, s.vbo);
  gl.bufferSubData(gl.ARRAY_BUFFER, m.uploaded * 12, m.pts, m.uploaded * 3, (m.n - m.uploaded) * 3);
  m.uploaded = m.n;
}

// particles, additively into a half-float buffer
const aspect = w / h;
const is3d = m.mode === 2;
let mvp = ctx.utils.mat4.identity(), size = Math.max(1.3, m.spacing * scale2d * 1.25);
if (is3d) {
  const k = 1 / s.view;
  mvp = ctx.utils.mat4.multiply(s.camera.getViewProjection(aspect), ctx.utils.mat4.fromScaling(k, k, k));
  const fit = Math.min(1, aspect); // keep the cluster inside a portrait frame too
  size = m.spacing * k * (h / 2) / Math.tan(20 * Math.PI / 180) * 1.25;
  mvp = ctx.utils.mat4.multiply(ctx.utils.mat4.fromScaling(fit, fit, 1), mvp);
  size *= fit;
}
gl.bindFramebuffer(gl.FRAMEBUFFER, s.fbo);
gl.viewport(0, 0, w, h);
gl.clearColor(0, 0, 0, 0);
gl.clear(gl.COLOR_BUFFER_BIT);
gl.enable(gl.BLEND);
gl.blendFunc(gl.ONE, gl.ONE);
gl.useProgram(s.ptProg);
const palette = m.mode;
const common = { u_mvp: mvp, u_is3d: is3d ? 1 : 0, u_count: m.n, u_res: [w, h], u_center: center, u_scale2d: scale2d,
  u_newest: Math.max(10, m.n * 0.015), u_palette: palette, u_gain: Math.min(2.2, Math.max(1, 2.6 / size)) }; // tiny points get brighter so a big cluster doesn't dim
gl.bindVertexArray(s.vao);
ctx.utils.setUniforms(s.ptProg, { ...common, u_size: size, u_halo: 4 });
gl.drawArrays(gl.POINTS, 0, m.n);
ctx.utils.setUniforms(s.ptProg, { u_halo: 1 });
gl.drawArrays(gl.POINTS, 0, m.n);
gl.bindVertexArray(null);
gl.disable(gl.BLEND);
gl.bindTexture(gl.TEXTURE_2D, s.tex);
gl.generateMipmap(gl.TEXTURE_2D);

gl.bindFramebuffer(gl.FRAMEBUFFER, null);
gl.viewport(0, 0, w, h);
const fade = s.phase === "fade" ? Math.max(0, 1 - s.phaseT) : Math.min(1, 0.3 + s.phaseT * 2);
gl.useProgram(s.outProg);
ctx.utils.bindTexture(s.outProg, "u_hdr", s.tex, 0);
ctx.utils.drawFullscreen(s.outProg, { u_exposure: u.u_glow, u_fade: fade, u_palette: palette });

ctx.publish("Mode", s.MODES[m.mode]);
ctx.publish("Particles", m.n);
ctx.publish("Cluster radius", Math.round(m.maxLen));
